"""Compare every deployed HTML response to this checkout's generated bytes."""
import hashlib
import json
from pathlib import Path
import sys
from urllib.request import Request, urlopen
from datetime import datetime, timezone

base = sys.argv[1].rstrip('/')
rows = []
for path in sorted(Path('site').glob('*.html')):
    url = f'{base}/{path.name}'
    with urlopen(Request(url, headers={'Cache-Control': 'no-cache'}), timeout=60) as response:
        raw = response.read()
        status = response.status
        final_url = response.url
    expected = hashlib.sha256(path.read_bytes()).hexdigest()
    actual = hashlib.sha256(raw).hexdigest()
    rows.append(dict(page=path.name, url=url, final_url=final_url, status=status, expected_sha256=expected,
                     actual_sha256=actual, matches=expected == actual))
report = dict(checked_at=datetime.now(timezone.utc).isoformat(), base_url=base,
              passed=all(row['matches'] for row in rows), pages=rows)
print(json.dumps(report, indent=2))
sys.exit(0 if report['passed'] else 1)
